mapper.update:
UPDATE cut_approval_node
SET status_code = #{query.newStatusCode},
    current_approver_user_id = #{query.currentApproverUserId},
    project_scope_version = #{query.projectScopeVersion},
    assessment_review_decision_code = #{query.assessmentReviewDecisionCode},
    assessment_review_reason = #{query.assessmentReviewReason},
    feedback = #{query.feedback},
    decision_at = #{query.decisionAt},
    version = #{query.expectedVersion} + 1,
    updater = #{query.updater},
    update_time = #{query.updateTime}
WHERE tenant_id = #{query.tenantId}
  AND id = #{query.approvalNodeId}
  AND status_code = #{query.expectedStatusCode}
  AND version = #{query.expectedVersion}
  AND deleted = b'0'
